function preload() {
  bg = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/paper.jpeg");
}

const W = 600;

let humanSize;
let circleSize;

let sc = new Scribble();
let floorY = 0;

function setup() {
  createCanvas(800, 600);
  frameRate(10);

  humanSize = 450;
  circleSize = width * 0.0125;

  human = new Human(0);

  sc.roughness = 2.5;
  sc.bowing = 2.0;
  sc.maxOffset = 2.0;

  const tmpVal = human.getValue();
  floorY = tmpVal[11].y;

  strokeWeight(5);
  stroke(0, 120);
}

function draw() {
  image(bg, 0, 0, width, height);

  push();
  translate(width / 2, height / 2 + 20);

  let xCoords = [-width / 2 - 50, width / 2 + 50, width / 2 + 50, -width / 2 - 50];
  let yCoords = [floorY + random(-10, 10), floorY + random(-10, 10), floorY + 100, floorY + 100];

  sc.scribbleFilling(xCoords, yCoords, 20, 315);

  human.draw();
  pop();
}

class Human {
  constructor(tmpX) {
    this.bmw = new BMWalker();
    this.x = tmpX;

    this.bmw.setSpeed(1.0);
    const bodyStructure = 1.0;
    const weight = 1.0;
    const nervousness = 0.0;
    const happiness = 2.0;
    this.bmw.setWalkerParam(bodyStructure, weight, nervousness, happiness);
  }

  draw() {
    const walkerHeight = humanSize;
    const markers = this.bmw.getMarkers(walkerHeight);

    const lineMarkers = this.bmw.getLineMarkers(walkerHeight);

    push();
    translate(this.x, 0);

    lineMarkers.forEach((m) => {
      let delta;
      if (m[0].i == 0) {
        delta = 95 / 2;
      } else {
        delta = 0;
      }
      sc.scribbleLine(m[0].x, m[0].y + delta, m[1].x, m[1].y);
    });


    markers.forEach((m) => {
      if (m.desc == 'Head') {
        sc.scribbleEllipse(m.x, m.y, 95, 95);
        sc.scribbleEllipse(m.x - 20, m.y - 15, 15, 15);
        sc.scribbleEllipse(m.x + 20, m.y - 15, 15, 15);
        sc.scribbleLine(m.x - 20, m.y + 20, m.x + 20, m.y + 20);
      }
    });
    pop();
  }

  getValue() {
    const walkerHeight = humanSize;
    const markers = this.bmw.getMarkers(walkerHeight);

    return markers;
  }
}

